#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int matches[10] = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};
    int x, y;
    long long ans = 0;

    cin >> x >> y;

    for (int i = x; i <= y; ++i) {
        int n = i;
        if (n == 0) ans += matches[0];

        while (n > 0) {
            ans += matches[n % 10];
            n /= 10;
        }
    }

    cout << ans;
    return 0;
}

